class InputCell(_Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        if new_value == self._value:
            return
        self._value = new_value
        affected = self._all_dependents()
        previous = [cell._value for cell in affected]
        # Recompute in topological order so each cell sees stable inputs.
        for cell in affected:
            cell._recompute()
        for cell, old in zip(affected, previous):
            if cell._value != old:
                cell._fire_callbacks()


class ComputeCell(_Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = list(inputs)
        self._compute_function = compute_function
        self._callbacks = []
        self.level = 1 + max((c.level for c in self._inputs), default=0)
        for cell in self._inputs:
            cell._dependents.append(self)
        self._recompute()

    @property
    def value(self):
        return self._value

    def _recompute(self):
        self._value = self._compute_function([c.value for c in self._inputs])

    def _fire_callbacks(self):
        for callback in list(self._callbacks):
            callback(self._value)

    def add_callback(self, callback):
        if callback not in self._callbacks:
            self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
